function GreetingCardLivePreview({ animation, effect, template, colors }: { animation: GreetingCardAnimation; effect: GreetingCardEffect; template: GreetingCardTemplate; colors: ReturnType<typeof useColors> }) { const progress = useRef(new Animated.Value(0)).current; useEffect(() => { progress.setValue(0); const loop = Animated.loop(Animated.sequence([Animated.timing(progress, { toValue: 1, duration: 1100, useNativeDriver: true }), Animated.delay(500), Animated.timing(progress, { toValue: 0, duration: 1100, useNativeDriver: true }), Animated.delay(500)])); loop.start(); return () => { loop.stop(); progress.stopAnimation(); }; }, [animation, progress]); const templateStyle = template === "champagne" ? { backgroundColor: "#7A5136", accent: "#F5D6A1", text: "#FFF5E6" } : template === "midnight" ? { backgroundColor: "#111827", accent: "#D4AF37", text: "#FFF7D6" } : template === "pearl" ? { backgroundColor: "#F5F0E8", accent: "#9A6B3F", text: "#2D2118" } : { backgroundColor: "#173B35", accent: "#D4AF37", text: "#FFF8D6" }; const motion = animation === "fade" || animation === "blur" ? { opacity: progress.interpolate({ inputRange: [0, 0.5, 1], outputRange: [1, 0.35, 1] }) } : animation === "slide" || animation === "wipe" ? { transform: [{ translateX: progress.interpolate({ inputRange: [0, 0.5, 1], outputRange: [0, 18, 0] }) }] } : animation === "zoom" || animation === "pulse" ? { transform: [{ scale: progress.interpolate({ inputRange: [0, 0.5, 1], outputRange: [1, 1.08, 1] }) }] } : animation === "bounce" ? { transform: [{ translateY: progress.interpolate({ inputRange: [0, 0.25, 0.55, 1], outputRange: [0, -7, 2, 0] }) }] } : animation === "tilt" ? { transform: [{ rotate: progress.interpolate({ inputRange: [0, 0.5, 1], outputRange: ["0deg", "4deg", "0deg"] }) }] } : animation === "flip" ? { transform: [{ rotateY: progress.interpolate({ inputRange: [0, 0.5, 1], outputRange: ["0deg", "85deg", "0deg"] }) }] } : { transform: [{ rotate: progress.interpolate({ inputRange: [0, 0.5, 1], outputRange: ["0deg", "180deg", "360deg"] }) }] }; return <View style={{ marginTop: 12, padding: 12, borderRadius: 16, backgroundColor: colors.surface, borderColor: colors.border, borderWidth: 1 }}><View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}><Text style={{ color: colors.foreground, fontWeight: "700" }}>Pratinjau langsung</Text><Text style={{ color: colors.primary, fontSize: 12 }}>Berjalan</Text></View><Animated.View style={[{ borderRadius: 14, padding: 14, backgroundColor: templateStyle.backgroundColor, borderColor: templateStyle.accent, borderWidth: 2, minHeight: 86, justifyContent: "center" }, effect === "card" && motion]}><Animated.View style={effect === "text" ? motion : undefined}><Text style={{ color: templateStyle.accent, fontSize: 11, fontWeight: "800", letterSpacing: 1 }}>✦ KARTU UCAPAN ✦</Text><Text style={{ color: templateStyle.text, fontSize: 18, fontWeight: "800", marginTop: 4 }}>Selamat hari spesial</Text><Text style={{ color: templateStyle.text, opacity: 0.8, fontSize: 12, marginTop: 3 }}>Dengan sentuhan mewah untuk Anda</Text></Animated.View></Animated.View></View>; }

